@startuml

abstract class Employee {
  + ssNo : string
  + name : string
  + email : string
}

class AdministrativeEmployee extends Employee {}

class ResearchAssistant extends Employee {
  + fieldOfResearch : string
}

class Lecturer extends ResearchAssistant {}

class Faculty {
  + name : string
}

class Institute {
  + name : string
  + address : string
}

class Course {
  + id : int
  + name : string
  + weeklyDuration : float
}

class Project {
  + name : string
  + startDate : date
  + endDate : date
}

class Participation {
  + hours : int
}

Employee "1" -- "0..1" Faculty : leads (dean)
Faculty "1" *-- "1..*" Institute
Institute "1..*" -- "1..*" ResearchAssistant : is assigned to
ResearchAssistant "1" -- "0..*" Participation
Participation "*" -- "1" Project
Lecturer "1..*" -- "1..*" Course : teaches

@enduml

